    slugHint: m.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "mod",
    name: m.title || m.name,
== lib/modsync/providers/ficsit.ts
/**
 * ficsit.app (Satisfactory Mod Repository) GraphQL API — game: satisfactory.
 * Public, no key. Files are served through Satisfactory Mod Manager's own
 * install path; we store metadata + link-through only (no per-mod license in
 * the listing, so nothing qualifies for mirroring).
 */

const API = "https://api.ficsit.app/v2/query";
const PAGE = 100;
const VER = "version game_version created_at size hash link";

export interface FsMod {
  name: string; mod_reference: string; short_description?: string | null; full_description?: string | null; logo?: string | null;
  downloads?: number | null; hidden?: boolean | null; last_version_date?: string | null; source_url?: string | null;
  authors?: { user?: { username?: string } | null }[];
  latestVersions?: { release?: FsVer | null; beta?: FsVer | null; alpha?: FsVer | null } | null;
}
type FsVer = { version: string; game_version?: string | null; created_at?: string | null; size?: number | null; hash?: string | null; link?: string | null };

export function parseFicsitMod(m: FsMod): NormalizedMod {
  const lv = m.latestVersions ?? {};
  const mk = (v: FsVer | null | undefined, channel: "release" | "beta" | "alpha") =>
    v ? { versionId: v.version, versionNumber: v.version, channel, gameVersions: v.game_version ? [v.game_version] : [], loaders: [], fileBytes: v.size ?? null, sha256: v.hash ?? null, fileUrl: null, publishedAt: v.created_at ? new Date(v.created_at) : null } : null;
  const versions = [mk(lv.release, "release"), mk(lv.beta, "beta"), mk(lv.alpha, "alpha")].filter((x): x is NonNullable<typeof x> => !!x);
